"""Every saas backend fixture, loaded from a descriptor generated by the real
tdx-system2 / tdx-domain2 create path. snowflake / databricks domains carry a
SCHEMA; salesforce is a creds clone (no schema); bigquery stages a dataset + GCS
prefix."""
from __future__ import annotations

from pathlib import Path

import pytest

from tabsdatax.itest.fixture import backend as common
from tabsdatax.itest.tdksystems2 import naming
from tabsdatax.itest.fixture.backends.bigquery import BigQueryDomain, BigQuerySystem
from tabsdatax.itest.fixture.backends.databricks import DatabricksDomain, DatabricksSystem
from tabsdatax.itest.fixture.backends.salesforce import SalesforceDomain, SalesforceSystem
from tabsdatax.itest.fixture.backends.snowflake import (
    SnowflakeDomain,
    SnowflakeSystem,
    snowflake_domain,
    snowflake_system,
)


def test_snowflake(provision):
    provision.system("snowflake", "s")
    assert common.load("s", SnowflakeSystem).account == "acct"
    provision.domain("snowflake", "s", "d")
    dom = common.load("d", SnowflakeDomain)
    # schema is the prefixed external name (compared case-insensitively —
    # Snowflake folds unquoted identifiers to upper case).
    assert dom.schema.lower() == naming.external_name("d").lower()
    assert dom.warehouse == "WH"


def test_databricks(provision):
    provision.system("databricks", "s")
    assert common.load("s", DatabricksSystem).catalog == "CAT"
    provision.domain("databricks", "s", "d")
    assert common.load("d", DatabricksDomain).schema == naming.external_name("d")


def test_salesforce(provision):
    provision.system("salesforce", "s")
    assert common.load("s", SalesforceSystem).url == "https://example.my.salesforce.com"
    provision.domain("salesforce", "s", "d")          # creds clone, no schema
    assert common.load("d", SalesforceDomain).token == "tok"


def test_bigquery(provision):
    provision.system("bigquery", "s")
    sysobj = common.load("s", BigQuerySystem)
    assert sysobj.project == "proj" and isinstance(sysobj.sys_path, Path)
    provision.domain("bigquery", "s", "d")
    dom = common.load("d", BigQueryDomain)
    assert dom.dataset == naming.external_name("d")  # prefixed name
    assert isinstance(dom.base_path, Path)


@pytest.fixture
def snowflake_ready(provision):
    provision.system("snowflake", "wh")
    provision.domain("snowflake", "wh", "sales")


@snowflake_system("wh")
@snowflake_domain("sales")
def test_saas_injection(
    snowflake_ready, system_wh: SnowflakeSystem, domain_sales: SnowflakeDomain
):
    assert isinstance(system_wh, SnowflakeSystem)
    assert isinstance(domain_sales, SnowflakeDomain)
    assert system_wh.name == "wh"
    assert domain_sales.name == "sales"          # logical name
    assert domain_sales.schema.lower() == naming.external_name("sales").lower()
